// RegisterIntents adds generated intent tools to the MCP server.
// This is called from RegisterTools when spec intents or recipe-lifted intents exist.
func RegisterIntents(s *server.MCPServer) {
	s.AddTool(
		mcplib.NewTool("confirm_the_aggregator_price_directly",
			mcplib.WithDescription("Confirm a Málaga rental price is real before booking: fetch DoYouSpain's cheapest Delpaso offer and Delpaso's own cheapest quote for the same dates, and return the delta. Málaga-only (Delpaso is a Málaga supplier). Returns a compact JSON summary."),
			mcplib.WithString("pickup", mcplib.Required(), mcplib.Description("Pickup date, dd/mm/yyyy or yyyy-mm-dd (e.g. 15/08/2026)")),
			mcplib.WithString("dropoff", mcplib.Required(), mcplib.Description("Drop-off date, dd/mm/yyyy or yyyy-mm-dd (e.g. 22/08/2026)")),
		),
		handleConfirmTheAggregatorPriceDirectly,
	)
}

// handleConfirmTheAggregatorPriceDirectly runs the confirm_the_aggregator_price_directly recipe intent: Puts DoYouSpain's cheapest Delpaso offer next to Delpaso's own quote with the delta.
func handleConfirmTheAggregatorPriceDirectly(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	if recipeCLIPathErr != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("companion CLI binary not found: %v", recipeCLIPathErr)), nil
	}

	input := req.GetArguments()
	args := []string{}
	args = append(args, "compare")
	var missingPickup bool
	args, missingPickup = appendRecipePositional(args, input["pickup"], true)
	if missingPickup {
		return mcplib.NewToolResultError("pickup is required"), nil
	}
	var missingDropoff bool
	args, missingDropoff = appendRecipePositional(args, input["dropoff"], true)
	if missingDropoff {
		return mcplib.NewToolResultError("dropoff is required"), nil
	}
	args = append(args, "--agent")

	out, err := cobratree.RunCLICommand(ctx, recipeCLIPath, args)
	if err != nil {
		return mcplib.NewToolResultError(err.Error()), nil
	}
	return mcplib.NewToolResultText(bound.Text(out)), nil
}

var (
	recipeCLIPath    string
	recipeCLIPathErr error
)

func init() {
	recipeCLIPath, recipeCLIPathErr = cobratree.SiblingCLIPath()
}

func appendRecipePositional(args []string, value any, required bool) ([]string, bool) {
	selected := recipeValueString(value)
	if selected == "" {
		return args, required
	}
	return append(args, selected), false
}

func appendRecipeStringFlag(args []string, name string, value any, defaultValue string, required bool, useEquals bool) ([]string, bool) {
	selected := defaultValue
	if value != nil {
		selected = recipeValueString(value)
	}
	if selected == "" {
		return args, required
	}
	if useEquals {
		return append(args, "--"+name+"="+selected), false
	}
	return append(args, "--"+name, selected), false
}

func appendRecipeBoolFlag(args []string, name string, value any, defaultValue bool) []string {
	selected := defaultValue
	if v, ok := value.(bool); ok {
		selected = v
	}
	if selected {
		return append(args, "--"+name)
	}
	return args
}

func recipeValueString(value any) string {
	switch v := value.(type) {
	case string:
		return strings.TrimSpace(v)
	case float64:
		return formatMCPParamValue(v)
	case bool:
		if v {
			return "true"
		}
		return "false"
	default:
		if value == nil {
			return ""
		}
		return fmt.Sprintf("%v", value)
	}
}
